create table if not exists public.tenants (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists public.tools (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), name text not null, kind text not null check (kind in ('rest','mcp')), scopes text[] not null default '{}', risk text not null check (risk in ('low','high')), descriptor jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), actor_id uuid, tool_id uuid references public.tools(id), decision text not null, input jsonb, output jsonb, latency_ms integer, cost_usd numeric(12,6), provider text, created_at timestamptz not null default now());
create table if not exists public.approval_requests (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), tool_id uuid not null references public.tools(id), actor_id uuid, status text not null default 'pending' check (status in ('pending','approved','denied')), created_at timestamptz not null default now());
alter table public.tools enable row level security; alter table public.audit_logs enable row level security; alter table public.approval_requests enable row level security;
create policy "tenant isolation tools" on public.tools for all to authenticated using (tenant_id::text = current_setting('app.tenant_id', true)) with check (tenant_id::text = current_setting('app.tenant_id', true));
create policy "tenant isolation audit" on public.audit_logs for all to authenticated using (tenant_id::text = current_setting('app.tenant_id', true)) with check (tenant_id::text = current_setting('app.tenant_id', true));
create policy "tenant isolation approvals" on public.approval_requests for all to authenticated using (tenant_id::text = current_setting('app.tenant_id', true)) with check (tenant_id::text = current_setting('app.tenant_id', true));
